#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <algorithm>
#include <random>
#include <stdint.h>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s:%d %s\n",__FILE__,__LINE__,cudaGetErrorString(e));exit(2);}}while(0)
__device__ __forceinline__ unsigned long long load(unsigned long long p,int ca){unsigned long long q;if(ca)asm volatile("ld.global.ca.u64 %0,[%1];":"=l"(q):"l"(p):"memory");else asm volatile("ld.global.cg.u64 %0,[%1];":"=l"(q):"l"(p):"memory");return q;}
__global__ void prepare(unsigned long long p,int ca,int n,unsigned long long *sink){if(threadIdx.x==0){for(int i=0;i<n;i++)p=load(p,ca);*sink=p;}}
__global__ void measure_kernel(unsigned long long p,int ca,int warm,int n,unsigned long long *out,unsigned long long *meta,int floor){if(threadIdx.x!=0)return;for(int i=0;i<warm;i++)p=load(p,ca);unsigned sm;asm volatile("mov.u32 %0,%%smid;":"=r"(sm));unsigned long long gt0,gt1,c0=clock64();asm volatile("mov.u64 %0,%%globaltimer;":"=l"(gt0));for(int i=0;i<n;i++){unsigned long long a,b,q;if(floor){asm volatile("{.reg .u64 a,b,q;.reg .pred ok;mov.u64 a,%%clock64;mov.u64 q,%3;setp.ne.u64 ok,q,0;mov.u64 b,0;@ok mov.u64 b,%%clock64;mov.u64 %0,a;mov.u64 %1,b;mov.u64 %2,q;}":"=l"(a),"=l"(b),"=l"(q):"l"(p):"memory");}else if(ca){asm volatile("{.reg .u64 a,b,q;.reg .pred ok;mov.u64 a,%%clock64;ld.global.ca.u64 q,[%3];setp.ne.u64 ok,q,0;mov.u64 b,0;@ok mov.u64 b,%%clock64;mov.u64 %0,a;mov.u64 %1,b;mov.u64 %2,q;}":"=l"(a),"=l"(b),"=l"(q):"l"(p):"memory");}else{asm volatile("{.reg .u64 a,b,q;.reg .pred ok;mov.u64 a,%%clock64;ld.global.cg.u64 q,[%3];setp.ne.u64 ok,q,0;mov.u64 b,0;@ok mov.u64 b,%%clock64;mov.u64 %0,a;mov.u64 %1,b;mov.u64 %2,q;}":"=l"(a),"=l"(b),"=l"(q):"l"(p):"memory");}p=q;out[i]=b-a;}asm volatile("mov.u64 %0,%%globaltimer;":"=l"(gt1));meta[0]=sm;meta[1]=clock64()-c0;meta[2]=gt1-gt0;meta[3]=p;}
int main(int argc,char**argv){int samples=8192,seeds=8;const char*only="all";if(argc>1)only=argv[1];if(argc>2)samples=atoi(argv[2]);if(argc>3)seeds=atoi(argv[3]);cudaDeviceProp prop;CK(cudaGetDeviceProperties(&prop,0));fprintf(stderr,"GPU=%s SM=%d L2=%d clock_kHz=%d\n",prop.name,prop.multiProcessorCount,prop.l2CacheSize,prop.clockRate);unsigned long long *out,*meta;CK(cudaMalloc(&out,samples*8));CK(cudaMalloc(&meta,32));std::vector<unsigned long long> vals(samples);unsigned long long m[4];std::vector<void*> keep;puts("seed,label,sample,cycles,smid,effective_mhz,allocation");for(int s=0;s<seeds;s++){std::vector<int> order={0,1,2,3};std::mt19937_64 rng(101+s);std::shuffle(order.begin(),order.end(),rng);for(int k:order){const char*name=k==0?"l1":k==1?"l2":k==2?"dram":"floor";if(std::string(only)!="all"&&std::string(only)!=name)continue;int nodes=k==0?64:k==1?8192:k==2?524288:64;size_t bytes=(size_t)nodes*128;unsigned long long *dev;CK(cudaMalloc(&dev,bytes));keep.push_back(dev);std::vector<unsigned long long> host(bytes/8,0);std::vector<int> perm(nodes);for(int i=0;i<nodes;i++)perm[i]=i;std::shuffle(perm.begin(),perm.end(),rng);for(int i=0;i<nodes;i++)host[perm[i]*16]=(unsigned long long)dev+(unsigned long long)perm[(i+1)%nodes]*128;CK(cudaMemcpy(dev,host.data(),bytes,cudaMemcpyHostToDevice));unsigned long long start=(unsigned long long)dev+(unsigned long long)perm[0]*128;int ca=k==0; if(k!=0&&k!=3){prepare<<<1,32>>>(start,ca,nodes,meta);CK(cudaDeviceSynchronize());}measure_kernel<<<1,32>>>(start,ca,k==0?nodes:0,samples,out,meta,k==3);CK(cudaDeviceSynchronize());CK(cudaMemcpy(vals.data(),out,samples*8,cudaMemcpyDeviceToHost));CK(cudaMemcpy(m,meta,32,cudaMemcpyDeviceToHost));unsigned long long expected=k==3?start:(unsigned long long)dev+(unsigned long long)perm[samples%nodes]*128;if(m[3]!=expected){fprintf(stderr,"pointer validation failed\n");return 3;}double mhz=1000.0*m[1]/m[2];fprintf(stderr,"seed=%d case=%s bytes=%zu sm=%llu mhz=%.2f pointer=PASS\n",101+s,name,bytes,m[0],mhz);for(int i=0;i<samples;i++)printf("%d,%s,%d,%llu,%llu,%.3f,%llu\n",101+s,name,i,vals[i],m[0],mhz,(unsigned long long)dev);}}for(void*p:keep)CK(cudaFree(p));}
